//------------- FUNCTION DECLARATIONS -------------

// Basic single pixel functions
void plot_pixel(int x, int y, short int line_color);
short int get_pixel(int x, int y);

// Shape drawing functions
void draw_line(int x0, int y0, int x1, int y1, short int line_color);
void draw_circle(int cx, int cy, int radius, short int color);
void draw_digit(int digit, int x, int y, short int color);
void draw_char(char ch, int x, int y, int scale, short colour);
void draw_play_button_green();
void draw_play_button_gray();
void draw_trash(short int light_color, short int dark_color);
void draw_trash_both(short int light_color, short int dark_color);
void draw_record_button_active();
void draw_record_button_inactive();
void draw_skip_button();
void fill_area(int x0, int x1, int y0, int y1, short int fill_color);
void fill_shape(int minX, int minY, int maxX, int maxY, short int fill_color, short int edge_color);

// Drawing & erasing play buttons
void draw_playhead(int tick, short int color);
void erase_playhead(int tick);

// Drawing main screen
void clear_screen();
void draw_main_screen(int recordActive, int chooseActive);
void erase_menu();
void update_left_menu();

// All mouse functions
void init_mouse();
void clear_ps2();
void poll_mouse();
void poll_keys();
void poll_keyboard();
void draw_cursor(int x, int y, short int color);
void erase_cursor(int x, int y, short int cursor_bg[]);
void cache_cursor_bg(int x, int y, short int cursor_bg[]);

void swap(int* x, int* y);
void update_audio();
void update_hardware();
void play_audio(const int audio_sample[], int num_of_samples);
double find_seconds_per_bar(int bpm);
void count_bars(int bpm, int bars, int continuous, int* stop);
void record_vocal_track(int num_bars, int bpm);

// Add/remove instrument
void draw_instrument_label(int type, int y);
void add_instrument();
void choose_instrument();
void remove_instrument();
void remove_instrument_at(int index);
void choose_piano();
void choose_snare();
void choose_hihat();
void choose_bass();
void choose_vocal();

// Sprite Functions
void erase_sprite(int x, int y, int w, int h);
void cache_sprite_bg(int x, int y, int w, int h);
void draw_sprite(int x, int y, int w, int h, const short int sprite[]);

void plot_pixel_both(int x, int y, short int color);
void draw_to_both(int x_start, int x_end, int y_start, int y_end, short int color);
void wait_for_vsync();

//---------- MAIN FUNCTION -----------
int main(void) {
	volatile int * pixel_ctrl_ptr = (int *)FRAME_BASE;
    /* Read location of the pixel buffer from the pixel buffer controller */
    pixel_buffer_start = *pixel_ctrl_ptr;

    //set front pixel buffer to Buffer 1
    *(pixel_ctrl_ptr + 1) = (int) &Buffer1; // first store the address in the  back buffer
	//now, swap the front/back buffers, to set the front buffer location
    wait_for_vsync();
    //initialize a pointer to the pixel buffer, used by drawing functions
    pixel_buffer_start = *pixel_ctrl_ptr;
    clear_screen(); // pixel_buffer_start points to the pixel buffer

    //set back pixel buffer to Buffer 2
    *(pixel_ctrl_ptr + 1) = (int) &Buffer2;
    pixel_buffer_start = *(pixel_ctrl_ptr + 1); // we draw on the back buffer
	clear_screen();

	//toggle states
	int trashActive = 0;
	int recordActive = 0;
	int chooseActive = 0;
	
	AUDIO_CTRL = 0xC;
    AUDIO_CTRL = 0x0;
	
	sample_pointers[0] = NULL;
	sample_pointers[1] = piano_samples;
	sample_pointers[2] = vocal_samples;
	sample_pointers[3] = hihat_samples;
	sample_pointers[4] = snare_samples;
	sample_pointers[5] = bass_samples;

	sample_lengths[2] = vocal_samples_n;
	sample_lengths[3] = hihat_samples_n;
	sample_lengths[4] = snare_samples_n;
	sample_lengths[5] = bass_samples_n;
	

	// CHANGED: Nested loop to initialize all 4 voices for every instrument to -1 (silent)
	for (int i = 0; i < MAX_INSTRUMENTS; i++) {
		for (int v = 0; v < MAX_VOICES; v++) {
			track_pos[i][v] = -1;
		}
	}

	init_mouse();
    clear_ps2();
	
	//draw to first buffer
    draw_main_screen(recordActive, chooseActive);
    cache_cursor_bg(mouseX, mouseY, cursor_bg_buffer1);
    draw_cursor(mouseX, mouseY, 0xFFFF);
	
	wait_for_vsync(); 
    pixel_buffer_start = *(pixel_ctrl_ptr + 1); 

	//draw to next buffer
	draw_main_screen(recordActive, chooseActive);
    cache_cursor_bg(mouseX, mouseY, cursor_bg_buffer2);
    draw_cursor(mouseX, mouseY, 0xFFFF);

	int prevMouseX1 = 160, prevMouseY1 = 120;  
	int prevMouseX2 = 160, prevMouseY2 = 120;

	// Per-buffer playhead tick trackers, same pattern as cursor position.
	// Each buffer independently tracks the last tick it drew so we erase+redraw
	// on the correct buffer every frame rather than ghosting on alternating frames.
	int last_drawn_tick1 = -1;
	int last_drawn_tick2 = -1;
	
	while (1) {
		wait_for_vsync(); 
		
		pixel_buffer_start = *(pixel_ctrl_ptr + 1);

		int *lastX_ptr, *lastY_ptr;
		int *lastTick_ptr;
		short int *cache_ptr;

		// Point to the coordinate and tick trackers for this specific buffer
		if (pixel_buffer_start == (int)&Buffer1) {
			lastX_ptr    = &prevMouseX1;
			lastY_ptr    = &prevMouseY1;
			lastTick_ptr = &last_drawn_tick1;
			cache_ptr 	 = cursor_bg_buffer1;
		} else {
			lastX_ptr    = &prevMouseX2;
			lastY_ptr    = &prevMouseY2;
			lastTick_ptr = &last_drawn_tick2;
			cache_ptr 	 = cursor_bg_buffer2;
		}

		// Erase cursor at this buffer's last known position
		erase_cursor(*lastX_ptr, *lastY_ptr, cache_ptr);
		poll_mouse();

		// Handle click events
		if (global_clicked) {
			int clickX = global_clickX;
			int clickY = global_clickY;
			global_clicked = 0;

			if (chooseActive) {
				int selected = 0;

				if (clickX > 108 && clickX < 158 && clickY > 74 && clickY < 123) {
					choose_piano(); 
					selected = 1;
				} else if (clickX > 161 && clickX < 211 && clickY > 74 && clickY < 123) {
					choose_vocal(); 
					selected = 1;
				} else if (clickX > 82 && clickX < 132 && clickY > 129 && clickY < 178) {
					choose_hihat(); 
					selected = 1;
				} else if (clickX > 135 && clickX < 185 && clickY > 129 && clickY < 178) {
					choose_snare(); 
					selected = 1;
				} else if (clickX > 188 && clickX < 238 && clickY > 129 && clickY < 178) {
					choose_bass(); 
					selected = 1;
				} else if (clickX > 0 && clickX < 21 && clickY > new_instrument_location_y1 && clickY < new_instrument_location_y2) {
					selected = 1;
				}

				if (selected) {
					chooseActive = 0;
						
					erase_menu();
					update_left_menu();
				}

			} else if (trashActive) {
				// clicking the trash icon again turns off remove mode
				if (clickX >= 7 && clickX <= 15 && clickY >= 5 && clickY <= 18) {
					trashActive = 0;

					int back  = *(pixel_ctrl_ptr + 1);
					int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

					short int *back_cache  = (back  == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;
					short int *other_cache = (other == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;

					int back_lastX = (back  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int back_lastY = (back  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					int other_lastX = (other  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int other_lastY = (other  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					
					pixel_buffer_start = back;
					erase_cursor(back_lastX, back_lastY, back_cache);
					pixel_buffer_start = other;
					erase_cursor(other_lastX, other_lastY, other_cache);
						
					draw_trash_both(0x041F, 0x0010);

					pixel_buffer_start = back;
					cache_cursor_bg(mouseX, mouseY, back_cache);
					pixel_buffer_start = other;
					cache_cursor_bg(mouseX, mouseY, other_cache);

				// clicking an instrument row removes it
				} else if (clickX > 0 && clickX < 21 && clickY > 29 && instrument_count > 0) {
					int row = (clickY - 30) / 20;
					if (row >= 0 && row < instrument_count) {
						remove_instrument_at(row);

						// Shift the per-row bar arrays down to match the row removal
						for (int r = row; r < instrument_count - 1; r++) {
							row_has_bar[r]          = row_has_bar[r + 1];
							last_active_samples[r]  = last_active_samples[r + 1];
							last_target_samples[r]  = last_target_samples[r + 1];
						}
						// Clear the now-vacated last slot
						row_has_bar[instrument_count - 1]         = 0;
						last_active_samples[instrument_count - 1] = 0;
						last_target_samples[instrument_count - 1] = 0;

						// FIX 2: Removed shadowed re-declaration of pixel_ctrl_ptr.
						// The outer pixel_ctrl_ptr is already in scope and correct.
						int back  = *(pixel_ctrl_ptr + 1);
						int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

						short int *back_cache  = (back  == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;
						short int *other_cache = (other == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;

						int back_lastX = (back  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
						int back_lastY = (back  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
						int other_lastX = (other  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
						int other_lastY = (other  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
						
						pixel_buffer_start = back;
						erase_cursor(back_lastX, back_lastY, back_cache);
						pixel_buffer_start = other;
						erase_cursor(other_lastX, other_lastY, other_cache);

						// Redraw sequencer grid area on both buffers
						for (int buf = 0; buf < 2; buf++) {
							pixel_buffer_start = (buf == 0) ? back : other;

							fill_area(21, 319, 29, 239, 0x0841);

							int major_lines[] = {59, 96, 133, 170, 207, 244, 281};
							for (int i = 0; i < 7; i++)
								draw_line(major_lines[i], 29, major_lines[i], 239, 0x2104);

							int minor_lines[] = {30, 40, 50, 68, 77, 86, 105, 114, 123,
												142, 151, 160, 179, 188, 197, 216, 225,
												234, 253, 262, 271, 290, 299, 308};
							for (int i = 0; i < 23; i++)
								draw_line(minor_lines[i], 29, minor_lines[i], 239, 0x1082);

							for (int r = 0; r < instrument_count; r++) {
								for (int col = 0; col < NUM_STEPS; col++) {
									if (sequencer_grid[r][col] == 1) {
										int x_start = step_x_bounds[col] + 1;
										int x_end   = step_x_bounds[col + 1] - 1;
										int y_start = 30 + (r * 20);
										int y_end   = y_start + 18;
										if (y_end < 240)
											fill_area(x_start, x_end, y_start, y_end, 0x881F);
									}
								}
							}
						}

						// update_left_menu draws to both buffers internally.
						// Restore pixel_buffer_start to back before calling it so
						// its internal buffer-selection logic has a consistent starting state.
						update_left_menu();
						
						// re-cache cursor on both buffers after all drawing is done
						pixel_buffer_start = back;
						cache_cursor_bg(mouseX, mouseY, back_cache);
						pixel_buffer_start = other;
						cache_cursor_bg(mouseX, mouseY, other_cache);

						pixel_buffer_start = back;
					}
				}
			} else {
				// trash icon click, enter remove mode
				if (clickX >= 7 && clickX <= 15 && clickY >= 5 && clickY <= 18) {
					trashActive = 1;

					int back  = *(pixel_ctrl_ptr + 1);
					int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

					short int *back_cache  = (back  == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;
					short int *other_cache = (other == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;

					int back_lastX = (back  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int back_lastY = (back  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					int other_lastX = (other  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int other_lastY = (other  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					
					pixel_buffer_start = back;
					erase_cursor(back_lastX, back_lastY, back_cache);
					pixel_buffer_start = other;
					erase_cursor(other_lastX, other_lastY, other_cache);
						
					draw_trash_both(0xF800, 0x8800);

					pixel_buffer_start = back;
					cache_cursor_bg(mouseX, mouseY, back_cache);
					pixel_buffer_start = other;
					cache_cursor_bg(mouseX, mouseY, other_cache);

				} else if (clickX >= 134 && clickX <= 149 && clickY > 5 && clickY < 16) {
					// --- SKIP TO START BUTTON ---
					int back  = *(pixel_ctrl_ptr + 1);
					int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

					short int *back_cache  = (back  == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;
					short int *other_cache = (other == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;

					int back_lastX = (back  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int back_lastY = (back  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					int other_lastX = (other  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int other_lastY = (other  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					
					pixel_buffer_start = back;
					erase_cursor(back_lastX, back_lastY, back_cache);
					pixel_buffer_start = other;
					erase_cursor(other_lastX, other_lastY, other_cache);
					
					// 1. Reset the playhead and sample timing to absolute zero
					// 1. Reset the playhead and sample timing to absolute zero
					current_tick = 0; 
					sample_counter = 0;
					
					// 2. Silence all currently playing notes so they don't overlap the restart
					for (int i = 0; i < MAX_INSTRUMENTS; i++) {
						for (int v = 0; v < MAX_VOICES; v++) {
							track_pos[i][v] = -1;
						}
					}
					
					// 3. If it is actively playing, immediately trigger the instruments on step 0
					if (playActive) {
						for (int i = 0; i < instrument_count; i++) {
							if (sequencer_grid[i][0]) {
								track_pos[i][0] = 0; 
							}
						}
					}

					pixel_buffer_start = back;
					cache_cursor_bg(mouseX, mouseY, back_cache);
					pixel_buffer_start = other;
					cache_cursor_bg(mouseX, mouseY, other_cache);
				} else if (clickX > 149 && clickX < 169 && clickY > 5 && clickY < 16) {
					playActive = !playActive;
					int back  = *(pixel_ctrl_ptr + 1);
					int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

					short int *back_cache  = (back  == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;
					short int *other_cache = (other == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;

					int back_lastX = (back  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int back_lastY = (back  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					int other_lastX = (other  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int other_lastY = (other  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					
					pixel_buffer_start = back;
					erase_cursor(back_lastX, back_lastY, back_cache);
					pixel_buffer_start = other;
					erase_cursor(other_lastX, other_lastY, other_cache);
						
					if (playActive) {
						draw_play_button_green();
					} else {
						draw_play_button_gray();
					}

					pixel_buffer_start = back;
					cache_cursor_bg(mouseX, mouseY, back_cache);
					pixel_buffer_start = other;
					cache_cursor_bg(mouseX, mouseY, other_cache);

				} else if (clickX > 169 && clickX < 184 && clickY > 5 && clickY < 16) {
					//recordActive = !recordActive;
					
					int back  = *(pixel_ctrl_ptr + 1);
					int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

					short int *back_cache  = (back  == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;
					short int *other_cache = (other == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;

					int back_lastX = (back  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int back_lastY = (back  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					int other_lastX = (other  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int other_lastY = (other  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					
					pixel_buffer_start = back;
					erase_cursor(back_lastX, back_lastY, back_cache);
					pixel_buffer_start = other;
					erase_cursor(other_lastX, other_lastY, other_cache);
					
					if (is_recording_mic || is_recording_piano || is_selecting_track) {
                        // Stop all recording processes
                        if (is_recording_mic) sample_lengths[2] = vocal_samples_n; 
                        if (is_recording_piano) sample_lengths[1] = piano_samples_n;
                        
                        if (record_target_row != -1) {
                            sequencer_grid[record_target_row][0] = 1;
                            draw_to_both(step_x_bounds[0]+1, step_x_bounds[1]-1, 30+(record_target_row*20), 30+(record_target_row*20)+18, 0x881F);
                        }
                        
                        is_recording_mic = 0;
                        is_recording_piano = 0;
                        is_selecting_track = 0;
                        record_target_row = -1;
                        draw_record_button_inactive();
                    } else {
                        // Start track selection
                        int rec_tracks = 0;
                        int last_rec_row = -1;
                        for (int r = 0; r < instrument_count; r++) {
                            if (instrument_types[r] == 1 || instrument_types[r] == 2) {
                                rec_tracks++;
                                last_rec_row = r;
                            }
                        }
                        
                        if (rec_tracks == 1) {
                            is_selecting_track = 1; 
                            global_clickX = 100; global_clickY = 35 + (last_rec_row * 20); global_clicked = 1; 
                        } else if (rec_tracks > 1) {
                            is_selecting_track = 1;
                            
                            volatile int *pixel_ctrl_ptr = (int *)FRAME_BASE;
                            int back = *(pixel_ctrl_ptr + 1);
                            int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;
                            for (int buf = 0; buf < 2; buf++) {
                                pixel_buffer_start = (buf == 0) ? back : other;
                                fill_area(170, 184, 5, 15, 0xFFE0); // Yellow to signify selection
                                draw_circle(177, 10, 3, 0xF800);
                                fill_shape(177 - 3, 10 - 3, 177 + 3, 10 + 3, 0xF800, 0xF800);
                            }
                            pixel_buffer_start = back;
                        }
                    }

					pixel_buffer_start = back;
					cache_cursor_bg(mouseX, mouseY, back_cache);
					pixel_buffer_start = other;
					cache_cursor_bg(mouseX, mouseY, other_cache);

				} else if (clickX > 0 && clickX < 21 && clickY > new_instrument_location_y1 && clickY < new_instrument_location_y2) {
					chooseActive = 1;
					int back  = *(pixel_ctrl_ptr + 1);
					int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

					short int *back_cache  = (back  == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;
					short int *other_cache = (other == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;

					int back_lastX = (back  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int back_lastY = (back  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					int other_lastX = (other  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int other_lastY = (other  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					
					pixel_buffer_start = back;
					erase_cursor(back_lastX, back_lastY, back_cache);
					pixel_buffer_start = other;
					erase_cursor(other_lastX, other_lastY, other_cache);

					choose_instrument(); 
					
					pixel_buffer_start = back;
					cache_cursor_bg(mouseX, mouseY, back_cache);
					pixel_buffer_start = other;
					cache_cursor_bg(mouseX, mouseY, other_cache);

				} else if (clickX > 21 && clickX < 319 && clickY > 29) {
					int back  = *(pixel_ctrl_ptr + 1);
					int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

					short int *back_cache  = (back  == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;
					short int *other_cache = (other == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;

					int back_lastX = (back  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int back_lastY = (back  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					int other_lastX = (other  == (int)&Buffer1) ? prevMouseX1 : prevMouseX2;
					int other_lastY = (other  == (int)&Buffer1) ? prevMouseY1 : prevMouseY2;
					
					pixel_buffer_start = back;
					erase_cursor(back_lastX, back_lastY, back_cache);
					pixel_buffer_start = other;
					erase_cursor(other_lastX, other_lastY, other_cache);

					int row = (clickY - 30) / 20;

					if (row < MAX_INSTRUMENTS && row < instrument_count) {
                        if (is_selecting_track) {
                            if (instrument_types[row] == 1 || instrument_types[row] == 2) {
                                is_selecting_track = 0;
                                record_target_row = row;
								target_record_samples = (int)(8.0 * (60.0 / beats_per_minute) * 8000.0);
								
								if (instrument_types[row] == 1) {
                                    if (target_record_samples > MAX_RECORD_SAMPLES) target_record_samples = MAX_RECORD_SAMPLES;
                                    piano_samples_n = 0;
                                    piano_phase = 0.0;
                                    is_recording_piano = 1;
                                } else if (instrument_types[row] == 2) {
                                    if (target_record_samples > MAX_VOCAL_SAMPLES) target_record_samples = MAX_VOCAL_SAMPLES;
                                    vocal_samples_n = 0;
                                    is_recording_mic = 1;
                                    volatile int * audio_ptr = (int *) AUDIO_BASE;
                                    while (((*(audio_ptr + 1) >> 8) & 0xFF) > 0 && (*(audio_ptr + 1) & 0xFF) > 0) {
                                        (void)*(audio_ptr + 2);
                                        (void)*(audio_ptr + 3);
                                    }
                                }
                                draw_record_button_active();
                            }
                        } else if (instrument_types[row] == 1 || instrument_types[row] == 2) {
							if (sequencer_grid[row][0] == 1) {
								// 1. Deactivate the sequence step
								sequencer_grid[row][0] = 0;
								
								// 2. Clear the audio buffer references
								if (instrument_types[row] == 1) {
									piano_samples_n = 0;
									sample_lengths[1] = 0;
								} else {
									vocal_samples_n = 0;
									sample_lengths[2] = 0;
								}

								// 3. Clear the visual bar and restore the background/grid
								int y_start = 30 + (row * 20);
								int y_end = y_start + 18;
								
								// Clear the row to black (using draw_to_both to ensure both buffers are wiped)
								draw_to_both(21, 319, y_start, y_end, 0x0000); 

								// Redraw the grid lines over the cleared area (matches your progress bar logic)
								int minor_lines[] = {30, 40, 50, 68, 77, 86, 105, 114, 123, 142, 151, 160, 179, 188, 197, 216, 225, 234, 253, 262, 271, 290, 299, 308};
								int major_lines[] = {59, 96, 133, 170, 207, 244, 281};

								for (int buf = 0; buf < 2; buf++) {
									// Toggle buffer manually for grid restoration if draw_to_both isn't used for lines
									// (Or just use draw_to_both inside these loops)
									for (int i = 0; i < 24; i++) 
										draw_to_both(minor_lines[i], minor_lines[i], y_start, y_end + 1, 0x1082);
									for (int i = 0; i < 7; i++) 
										draw_to_both(major_lines[i], major_lines[i], y_start, y_end + 1, 0x2104);
								}
								
								// Reset the latched draw row so the progress bar loop stops rendering it
								row_has_bar[row]          = 0;
								last_active_samples[row]  = 0;
								last_target_samples[row]  = 0;
                            }
                        } else if (instrument_types[row] > 2) {
                            int col = -1;
                            for (int i = 0; i < NUM_STEPS; i++) {
                                if (clickX >= step_x_bounds[i] && clickX < step_x_bounds[i + 1]) {
                                    col = i;
                                    break;
                                }
                            }

                            if (col != -1) {
                                sequencer_grid[row][col] = !sequencer_grid[row][col];
                                int x_start = step_x_bounds[col] + 1;
                                int x_end   = step_x_bounds[col + 1] - 1;
                                int y_start = 30 + (row * 20);
                                int y_end   = y_start + 18;

                                if (y_end < 240) {
                                    if (sequencer_grid[row][col] == 1) {
                                        draw_to_both(x_start, x_end, y_start, y_end, 0x881F);
                                        int voice_found = 0;
                                        for (int v = 0; v < MAX_VOICES; v++) {
                                            if (track_pos[row][v] == -1) {
                                                track_pos[row][v] = 0;
                                                voice_found = 1;
                                                break;
                                            }
                                        }
                                        if (!voice_found) track_pos[row][0] = 0;
                                    } else {
                                        draw_to_both(x_start, x_end, y_start, y_end, 0x0841);
                                    }
                                }
                            }
                        }
					}
					
					pixel_buffer_start = back;
					cache_cursor_bg(mouseX, mouseY, back_cache);
					pixel_buffer_start = other;
					cache_cursor_bg(mouseX, mouseY, other_cache);
				}
			}
		}

		// Render Progress Bar 

		// Decide which row to draw on
		// Latch the currently-recording row so it stays drawn after recording stops.
		if (record_target_row != -1) {
			row_has_bar[record_target_row] = 1;
			last_target_samples[record_target_row] = target_record_samples;
			// Update live sample count for the row being recorded right now.
			if (is_recording_mic || is_recording_piano) {
				last_active_samples[record_target_row] =
					is_recording_mic ? vocal_samples_n : piano_samples_n;
			}
		}

		// Only draw if we have a valid row (current OR latched)
		for (int draw_row = 0; draw_row < instrument_count; draw_row++) {
			if (!row_has_bar[draw_row]) continue;

			int active_samples  = last_active_samples[draw_row];
			int tgt_samples     = last_target_samples[draw_row];
			if (tgt_samples <= 0) continue;

			int x_current = 21 + (int)(((float)active_samples / tgt_samples) * 298.0);
			int x_max = 21 + 298;
			if (x_current > x_max) x_current = x_max;

			int y_start = 30 + (draw_row * 20);
			int y_end   = y_start + 18;

			if (y_end < 240) {
				// Determine if the menu is vertically blocking this specific row
				int is_menu_blocking = (chooseActive && y_end >= 50 && y_start <= 190);

				// 1. REDRAW BACKGROUND
				if (is_menu_blocking) {
					fill_area(22, 69, y_start, y_end, 0x0000);   // Left of menu
					fill_area(251, 319, y_start, y_end, 0x0000); // Right of menu
				} else {
					fill_area(22, 319, y_start, y_end, 0x0000);  // Full width
				}

				// 2. REDRAW GRID LINES
				int minor_lines[] = {30, 40, 50, 68, 77, 86, 105, 114, 123, 142, 151, 160, 179, 188, 197, 216, 225, 234, 253, 262, 271, 290, 299, 308};
				for (int i = 0; i < 24; i++) {
					// Only draw line if it's NOT inside the menu X-bounds (70-250)
					if (!is_menu_blocking || (minor_lines[i] < 70 || minor_lines[i] > 320)) {
						draw_line(minor_lines[i], y_start, minor_lines[i], y_end + 1, 0x1082);
					}
				}

				// 3. REDRAW MAJOR BARS
				int major_lines[] = {59, 96, 133, 170, 207, 244, 281};
				for (int i = 0; i < 7; i++) {
					if (!is_menu_blocking || (major_lines[i] < 70 || major_lines[i] > 250)) {
						draw_line(major_lines[i], y_start, major_lines[i], y_end + 1, 0x2104);
					}
				}

				// 4. DRAW PROGRESS BAR (Already has your split logic)
				if (x_current > 21) {
					if (is_menu_blocking) {
						int segment1_end = (x_current < 70) ? x_current : 69;
						if (segment1_end >= 22) fill_area(22, segment1_end, y_start, y_end, 0x881F);
						if (x_current > 250)    fill_area(251, x_current, y_start, y_end, 0x881F);
					} else {
						fill_area(22, x_current, y_start, y_end, 0x881F);
					}
				}

				// 5. REDRAW PLAYHEAD (Row-Specific Clipping)
				if (playActive && current_tick >= 0) {
					// Find the center X of the current tick
					int ph_x = step_x_bounds[current_tick] + (step_x_bounds[current_tick + 1] - step_x_bounds[current_tick]) / 2;

					// Only draw if playhead is NOT behind the menu OR if the menu isn't blocking this row
					if (!is_menu_blocking || (ph_x < 70 || ph_x > 250)) {
						// Draw only the segment of the playhead that exists within this row's Y-bounds
						draw_line(ph_x, y_start, ph_x, y_end, 0xFFFF);
					}
				}
			}
		}


		// Auto Stop Recording
		int active_samples = is_recording_mic ? vocal_samples_n : piano_samples_n;

		if ((is_recording_mic || is_recording_piano) && active_samples >= target_record_samples) {
			if (is_recording_mic) sample_lengths[2] = vocal_samples_n; 
			if (is_recording_piano) sample_lengths[1] = piano_samples_n;

			if (record_target_row != -1) {
				sequencer_grid[record_target_row][0] = 1;
				draw_to_both(
					step_x_bounds[0]+1,
					step_x_bounds[1]-1,
					30+(record_target_row*20),
					30+(record_target_row*20)+18,
					0x881F
				);
			}

			is_recording_mic = 0;
			is_recording_piano = 0;

			draw_record_button_inactive();
		}

		// 4. Playhead delta rendering — per buffer.
		// Each buffer erases its own stale tick and draws the current one,
		// preventing ghost playheads on alternating frames.
		// NEW — always redraw playhead after progress bar may have wiped it
		if (*lastTick_ptr != current_tick) {
			if (*lastTick_ptr >= 0) erase_playhead(*lastTick_ptr);
			*lastTick_ptr = current_tick;
		}

		if (current_tick >= 0 && !chooseActive) {
			draw_playhead(current_tick, 0xFFFF);
		}
		
		// 5. Cache and draw cursor at current mouse position
		cache_cursor_bg(mouseX, mouseY, cache_ptr);
		draw_cursor(mouseX, mouseY, 0xFFFF);

		// 6. Update this buffer's tracked cursor position
		*lastX_ptr = mouseX;
		*lastY_ptr = mouseY;

		// 7. Update hardware and swap buffers
		update_hardware();

	}
}

//------------ HARDWARE SYNCHRONIZATION FUNCTIONS ---------------
void update_hardware() {
	update_audio();
    poll_keyboard();
    poll_keys();
}

void poll_keys() {
    volatile int * key_ptr = (int *) KEY_BASE;
    int current_key_state = *key_ptr;
    static int last_key_state = 0;
    
    if ((current_key_state & 0x1) && !(last_key_state & 0x1)) {
        piano_octave_multiplier *= 0.5;
        piano_current_freq = piano_base_freq * piano_octave_multiplier;
    }
    if ((current_key_state & 0x2) && !(last_key_state & 0x2)) {
        if (piano_octave_multiplier < 8.0) {
            piano_octave_multiplier *= 2.0;
            piano_current_freq = piano_base_freq * piano_octave_multiplier;
        }
    }
    last_key_state = current_key_state;
}

void poll_keyboard() {
    volatile int* ps2_kb_ptr = (int*)PS2_KB_BASE;
    int data;
    static int piano_break_code = 0;
    
    while (1) {
        data = *ps2_kb_ptr;
        if ((data & 0x8000) == 0) return;
        
        unsigned char code = data & 0xFF;
        if (code == 0xE0) continue;
        
        if (code == 0xF0) {
            piano_break_code = 1;
        } else {
            if (piano_break_code) {
                if (code == piano_current_playing_code) {
                    piano_is_playing = 0;
                    piano_current_playing_code = 0;
                }
                piano_break_code = 0;
            } else {
                if (code != piano_current_playing_code) {
                    piano_is_playing = 1;
                    piano_current_playing_code = code;
                    
                    if (code == 0x1C)      piano_base_freq = note_frequencies[0];  // A
                    else if (code == 0x1D) piano_base_freq = note_frequencies[1];  // W
                    else if (code == 0x1B) piano_base_freq = note_frequencies[2];  // S
                    else if (code == 0x24) piano_base_freq = note_frequencies[3];  // E
                    else if (code == 0x23) piano_base_freq = note_frequencies[4];  // D
                    else if (code == 0x2B) piano_base_freq = note_frequencies[5];  // F
                    else if (code == 0x2C) piano_base_freq = note_frequencies[6];  // T
                    else if (code == 0x34) piano_base_freq = note_frequencies[7];  // G
                    else if (code == 0x35) piano_base_freq = note_frequencies[8];  // Y
                    else if (code == 0x33) piano_base_freq = note_frequencies[9];  // H
                    else if (code == 0x3C) piano_base_freq = note_frequencies[10]; // U
                    else if (code == 0x3B) piano_base_freq = note_frequencies[11]; // J
                    else if (code == 0x42) piano_base_freq = note_frequencies[12]; // K
                    
                    piano_current_freq = piano_base_freq * piano_octave_multiplier;
                }
            }
        }
    }
}

void update_audio() {
    // --- MIC RECORDING PHASE ---
    if (is_recording_mic) {
        volatile int * audio_ptr = (int *) AUDIO_BASE;
        int fifospace = *(audio_ptr + 1); 
        int rarc = (fifospace >> 8) & 0xFF;

        while (rarc > 0 && vocal_samples_n < target_record_samples) {
            int left = *(audio_ptr + 2);
            (void)*(audio_ptr + 3);
            vocal_samples[vocal_samples_n] = left; 
            vocal_samples_n++;
            rarc--;
        }
    }

	int left_space = (AUDIO_FIFOSPACE >> 24) & 0xFF;
	int right_space = (AUDIO_FIFOSPACE >> 16) & 0xFF;
	int space = (left_space < right_space) ? left_space : right_space;

	while (space > 0) {
		long long mixed_sample = 0;

        // --- Generate Live Piano Audio ---
        if (is_recording_piano && piano_samples_n < target_record_samples) {
            int p_sample = 0;
            if (piano_is_playing && piano_current_freq > 0.0) {
                piano_phase += (piano_current_freq / 8000.0);
                if (piano_phase >= 1.0) piano_phase -= 1.0;
                p_sample = (piano_phase < 0.5) ? 10000000 : -10000000;
            }
            piano_samples[piano_samples_n++] = p_sample;
            mixed_sample += p_sample * 4; // Add to output mix so user hears it live!
        }

		// --- MIXING PHASE ---
		for (int i = 0; i < instrument_count; i++) {
			int type = instrument_types[i];

			for (int v = 0; v < MAX_VOICES; v++) {
				if (track_pos[i][v] != -1 && sample_lengths[type] > 0) {
					if 	(type == 5) {
						mixed_sample += (sample_pointers[type][track_pos[i][v]] * 3);
					}
					else if (type == 1){ // make piano louder
						mixed_sample += (sample_pointers[type][track_pos[i][v]] * 4);
					}
					else if (type == 2) {
						mixed_sample += (sample_pointers[type][track_pos[i][v]]);
					}
					else {
						mixed_sample += (sample_pointers[type][track_pos[i][v]] * 2);
					}
					track_pos[i][v]++;

					if (track_pos[i][v] >= sample_lengths[type]) {
						track_pos[i][v] = -1; 
					}
				}
			}
		}

		// Hard clipping protection
		if (mixed_sample > 2147483647LL) mixed_sample = 2147483647LL;
		if (mixed_sample < -2147483648LL) mixed_sample = -2147483648LL;

		AUDIO_LEFT = (int)mixed_sample;
		AUDIO_RIGHT = (int)mixed_sample;

		space--;

		// --- 2. SEQUENCER TICK PHASE ---
		if (playActive) {
			sample_counter++;
			int samples_per_step = 120000 / beats_per_minute;

			if (sample_counter >= samples_per_step) {
				sample_counter = 0;
				current_tick = (current_tick + 1) % NUM_STEPS;

				for (int i = 0; i < instrument_count; i++) {
					if (sequencer_grid[i][current_tick]) {
						int voice_found = 0;
						for (int v = 0; v < MAX_VOICES; v++) {
							if (track_pos[i][v] == -1) {
								track_pos[i][v] = 0; // Trigger the sample here
								voice_found = 1;
								break; 
							}
						}

						if (!voice_found) {
							int oldest_voice = 0;
							int max_pos = -1;
							for(int v = 0; v < MAX_VOICES; v++) {
								if(track_pos[i][v] > max_pos) {
									max_pos = track_pos[i][v];
									oldest_voice = v;
								}
							}
							track_pos[i][oldest_voice] = 0; 
						}
					}
				}
			}
		}
	}
}

void poll_mouse() {
	volatile int* ps2_ptr = (int*)PS2_BASE;
	int data;
	static int prev_btn = 0;

	while (1) {
		// check if byte1 is available
		data = *ps2_ptr;
		if ((data & 0x8000) == 0) return; // no data at all, exit

		int byte1 = data & 0xFF;
		if (!(byte1 & 0x08)) return;

		// wait for byte2
		do {
			data = *ps2_ptr;
		} while ((data & 0x8000) == 0);
		
		int byte2 = data & 0xFF;
		
		// wait for byte3
		do {
			data = *ps2_ptr;
		} while ((data & 0x8000) == 0);
		
		int byte3 = data & 0xFF;

		// sign extend correctly
		int dx = (int)(signed char)byte2;
		int dy = (int)(signed char)byte3;

		if (byte1 & 0x40) dx = 0;
		if (byte1 & 0x80) dy = 0;

		dx = dx / 2;
		dy = dy / 2;

		mouseX += dx;
		mouseY -= dy;

		// Bound the mouse to the screen
		if (mouseX < 0) 	mouseX = 0;
		if (mouseX > 319) 	mouseX = 319;
		if (mouseY < 0) 	mouseY = 0;
		if (mouseY > 239) 	mouseY = 239;

		int current_btn = byte1 & 0x01;
		
		if (current_btn && !prev_btn) {
			global_clicked = 1;
			global_clickX = mouseX;
			global_clickY = mouseY;
		}
		
		prev_btn = current_btn;
	}
}

//------------ PLAYHEAD FUNCTIONS ---------------

// Draws a white vertical line through the centre of the given step column
void draw_playhead(int tick, short int color) {
	int x =
		step_x_bounds[tick] + (step_x_bounds[tick + 1] - step_x_bounds[tick]) / 2;
	for (int y = 29; y < 240; y++) {
		plot_pixel_both(x, y, color);
	}
}

// Erases the playhead by restoring each pixel to its correct background color.
// Starts from y=30 to avoid the off-by-one at the grid boundary.
void erase_playhead(int tick) {
	int x =
		step_x_bounds[tick] + (step_x_bounds[tick + 1] - step_x_bounds[tick]) / 2;
	for (int y = 29; y < 240; y++) {
		short int restore_color = 0x0841;
		if (y >= 30) {
			int row = (y - 30) / 20;
			int offset = (y - 30) % 20;
			if (row >= 0 && row < instrument_count && sequencer_grid[row][tick] == 1) {
				if (offset >= 0 && offset < 19) {restore_color = 0x881F;}
			}
		}
		plot_pixel_both(x, y, restore_color);
	}
}

//------------ DRAWING FUNCTIONS ---------------

void cache_cursor_bg(int x, int y, short int cursor_bg[]) {
    if (x > 0 && x < 319 && y > 0 && y < 239) {
        int i = 0;
        for (int dy = -2; dy <= 2; dy++) {
            for (int dx = -2; dx <= 2; dx++) {
                cursor_bg[i++] = get_pixel(x + dx, y + dy);
            }
        }
    }
}

void erase_cursor(int x, int y, short int cursor_bg[]) {
    if (x > 0 && x < 319 && y > 0 && y < 239) {
        int i = 0;
        for (int dy = -2; dy <= 2; dy++) {
            for (int dx = -2; dx <= 2; dx++) {
                plot_pixel(x + dx, y + dy, cursor_bg[i++]);
            }
        }
    }
}


void draw_cursor(int x, int y, short int color) {
	if (x + 1 < 319 && y < 239 && x - 1 >= 0 && y - 1 >= 0) {
		plot_pixel(x, y, color);
		plot_pixel(x + 1, y, color);
		plot_pixel(x - 1, y, color);
		plot_pixel(x, y + 1, color);
		plot_pixel(x, y - 1, color);
	}
}

void erase_menu() {
    draw_to_both(70, 250, 50, 190, 0x0841);

    // redraw grid lines on both buffers
    volatile int *pixel_ctrl_ptr = (int *)FRAME_BASE;
    int back = *(pixel_ctrl_ptr + 1);
    int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

    for (int buf = 0; buf < 2; buf++) {
        pixel_buffer_start = (buf == 0) ? back : other;

        int major_lines[] = {96, 133, 170, 207, 244};
        for (int i = 0; i < 5; i++)
            draw_line(major_lines[i], 50, major_lines[i], 191, 0x2104);

        int minor_lines[] = {77, 86, 105, 114, 123, 142, 151,
                             160, 179, 188, 197, 216, 225, 234};
        for (int i = 0; i < 14; i++)
            draw_line(minor_lines[i], 50, minor_lines[i], 191, 0x1082);

        for (int row = 0; row < instrument_count; row++) {
            for (int col = 0; col < NUM_STEPS; col++) {
                if (sequencer_grid[row][col] == 1) {
                    int x_start = step_x_bounds[col] + 1;
                    int x_end = step_x_bounds[col + 1] - 1;
                    int y_start = 30 + (row * 20);
                    int y_end = y_start + 18;
					
                    if (x_end >= 70 && x_start <= 250 && y_end >= 50 && y_start <= 190) {
                        fill_area(x_start, x_end, y_start, y_end - 1, 0x881F);
                    }
                }
            }
        }

		if (current_tick >= 0) {
            int px = step_x_bounds[current_tick] + (step_x_bounds[current_tick + 1] - step_x_bounds[current_tick]) / 2;
            if (px >= 70 && px <= 250) {
                draw_line(px, 50, px, 190, 0xFFFF);
            }
        }
    
    }

    pixel_buffer_start = back; // restore
}

void update_left_menu() {
    volatile int *pixel_ctrl_ptr = (int *)FRAME_BASE;
    int back = *(pixel_ctrl_ptr + 1);
    int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

    for (int buf = 0; buf < 2; buf++) {
        pixel_buffer_start = (buf == 0) ? back : other;

        // clear entire left panel
        fill_area(1, 20, 21, 239, 0x39E7);
		draw_line(0, 0, 0, 239, 0x2104);
        draw_line(21, 30, 21, 239, 0x2104);

        // draw each instrument slot: top border, then sprite
        for (int i = 0; i < instrument_count; i++) {
            // top border of this slot
            draw_line(0, instrument_separator_positions[i],
                      21, instrument_separator_positions[i], 0x2104);
            // bottom border of this slot (= top border of next slot or plus zone)
            draw_line(0, instrument_separator_positions[i] + 20,
                      21, instrument_separator_positions[i] + 20, 0x2104);
            draw_instrument_label(instrument_types[i], instrument_label_positions[i]);
        }

        // plus zone borders and symbol drawn last
        draw_line(0, new_instrument_location_y1, 21, new_instrument_location_y1, 0x2104);
        draw_line(0, new_instrument_location_y2, 21, new_instrument_location_y2, 0x2104);
		draw_line(7, add_instrument_plus_y0, 14, add_instrument_plus_y0, 0xBDF7);
		draw_line(10, add_instrument_plus_y1, 10, add_instrument_plus_y2, 0xBDF7);
    }

    pixel_buffer_start = back;
}

void add_instrument() {
	if ((new_instrument_location_y2 + 20) > 240) {return;}
		
	int temp = new_instrument_location_y2;
	new_instrument_location_y2 += 20;
	new_instrument_location_y1 = temp;
	
	//horizontal line
	add_instrument_plus_y0 = new_instrument_location_y1 + 10;
	
	//for vertical line
	add_instrument_plus_y1 = new_instrument_location_y1 + 7; 
	add_instrument_plus_y2 = new_instrument_location_y1 + 14;
}

void remove_instrument() {
	if ((new_instrument_location_y1 - 20) < 29) {return;}

	int temp = new_instrument_location_y1;
	new_instrument_location_y1 -= 20;
	new_instrument_location_y2 = temp;
	
	//horizontal line
	add_instrument_plus_y0 = new_instrument_location_y2 - 10;
	
	//for vertical line
	add_instrument_plus_y1 = new_instrument_location_y2 - 13; 
	add_instrument_plus_y2 = new_instrument_location_y2 - 6;
}

void remove_instrument_at(int index) {
    // silence voices for removed instrument
    for (int v = 0; v < MAX_VOICES; v++)
        track_pos[index][v] = -1;

    // shift everything down
    for (int i = index; i < instrument_count - 1; i++) {
        instrument_types[i] = instrument_types[i + 1];
        for (int col = 0; col < NUM_STEPS; col++)
            sequencer_grid[i][col] = sequencer_grid[i + 1][col];
        for (int v = 0; v < MAX_VOICES; v++)
            track_pos[i][v] = track_pos[i + 1][v];
    }

    // clear the last slot
    instrument_types[instrument_count - 1] = 0;
    for (int col = 0; col < NUM_STEPS; col++)
        sequencer_grid[instrument_count - 1][col] = 0;
    for (int v = 0; v < MAX_VOICES; v++)
        track_pos[instrument_count - 1][v] = -1;

    instrument_count--;
    remove_instrument(); // updates new_instrument_location_y1/y2 globals

    // recompute separator and label positions from scratch based on slot index
    for (int i = 0; i < instrument_count; i++) {
		instrument_separator_positions[i] = 29 + (i * 20);
		instrument_label_positions[i]     = 37 + (i * 20);
    }
}

